import{_ as t,o as e,c as i,a5 as o}from"./chunks/framework.Bhkz_BpM.js";const m=JSON.parse('{"title":"Mission: 电机控制全栈知识体系交互式学习","description":"","frontmatter":{"date":"2026-06-13T00:00:00.000Z","section":"电机控制","chapter":"learning-workspace","chapterTitle":"学习工作区","chapterOrder":5,"category":"学习工作区","source":"motor","visibility":"public","title":"Mission: 电机控制全栈知识体系交互式学习","tags":["motor-control"],"status":"learning","summary":"作为有实践经验的电机控制工程师，需要将零散的知识系统化、体系化，建立从硬件底层到高级算法的完整认知框架。同时作为知识管理工具，方便后续查阅和分享。","navGroup":"入门与索引","navGroupOrder":10},"headers":[],"relativePath":"content/motor/learning-workspace/MISSION.md","filePath":"content/motor/learning-workspace/MISSION.md","lastUpdated":1783096495000}'),r={name:"content/motor/learning-workspace/MISSION.md"};function l(n,a,s,c,h,d){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="mission-电机控制全栈知识体系交互式学习" tabindex="-1">Mission: 电机控制全栈知识体系交互式学习 <a class="header-anchor" href="#mission-电机控制全栈知识体系交互式学习" aria-label="Permalink to &quot;Mission: 电机控制全栈知识体系交互式学习&quot;">​</a></h1><h2 id="动机" tabindex="-1">动机 <a class="header-anchor" href="#动机" aria-label="Permalink to &quot;动机&quot;">​</a></h2><p>作为有实践经验的电机控制工程师，需要将零散的知识系统化、体系化，建立从硬件底层到高级算法的完整认知框架。同时作为知识管理工具，方便后续查阅和分享。</p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><ol><li><strong>全面掌握</strong> 14条学习路径的核心知识，建立&quot;硬件-算法-系统&quot;三维认知</li><li><strong>知识管理</strong> 将静态知识库转化为可交互、可追踪、可检索的学习资源</li><li><strong>深度理解</strong> 通过交互式测验、可视化动画、代码对照深化理解</li><li><strong>工程转化</strong> 将理论知识转化为可落地的工程判断力</li></ol><h2 id="当前水平" tabindex="-1">当前水平 <a class="header-anchor" href="#当前水平" aria-label="Permalink to &quot;当前水平&quot;">​</a></h2><ul><li>有实践经验：实现过有感FOC，理解SVPWM和电流采样</li><li>最近发展区：无感观测器设计、MTPA/弱磁、ADRC/MPC等高级算法</li><li>短板：控制理论系统化不足、硬件-算法桥接理解不深</li></ul><h2 id="学习策略" tabindex="-1">学习策略 <a class="header-anchor" href="#学习策略" aria-label="Permalink to &quot;学习策略&quot;">​</a></h2><ul><li>以算法路径为核心锚点，向硬件和控制理论双向辐射</li><li>每个模块：先读核心摘要 → 交互式课程深化 → 评估测验验证 → 代码对照实践</li><li>利用交叉引用系统建立模块间关联</li></ul><h2 id="成功标准" tabindex="-1">成功标准 <a class="header-anchor" href="#成功标准" aria-label="Permalink to &quot;成功标准&quot;">​</a></h2><ul><li>每条路径评估正确率 &gt;= 80%</li><li>能独立解释硬件约束如何影响算法设计决策</li><li>能从零推导FOC坐标变换链和PI参数设计</li></ul>',11)])])}const p=t(r,[["render",l]]);export{m as __pageData,p as default};
